import{_ as e,o,c as t,a3 as r}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"How Far Are Surgeons from Surgical World Models? A Pilot Study on Zero-shot Surgical Video Generation with Expert Assessment","description":"","frontmatter":{"title":"How Far Are Surgeons from Surgical World Models? A Pilot Study on Zero-shot Surgical Video Generation with Expert Assessment","arxiv":"2511.01775","date":"2025-11-03","authors":"Zhen Chen, Qing Xu, Jinlin Wu, Biao Yang, Yuhao Zhai, Geng Guo, Jing Zhang, Yinlu Ding, Nassir Navab, Jiebo Luo","categories":"cs.CV, cs.AI, cs.MM","topics":"物理感知视频生成, 手术世界模型, 专家评测","outline":[2,2]},"headers":[],"relativePath":"papers/2511.01775.md","filePath":"papers/2511.01775.md","lastUpdated":null}'),n={name:"papers/2511.01775.md"};function s(i,a,l,p,h,d){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="how-far-are-surgeons-from-surgical-world-models-a-pilot-study-on-zero-shot-surgical-video-generation-with-expert-assessment" tabindex="-1">How Far Are Surgeons from Surgical World Models? A Pilot Study on Zero-shot Surgical Video Generation with Expert Assessment <a class="header-anchor" href="#how-far-are-surgeons-from-surgical-world-models-a-pilot-study-on-zero-shot-surgical-video-generation-with-expert-assessment" aria-label="Permalink to &quot;How Far Are Surgeons from Surgical World Models? A Pilot Study on Zero-shot Surgical Video Generation with Expert Assessment&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2511.01775" target="_blank" rel="noreferrer">2511.01775</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-11-03</td></tr><tr><td><strong>作者</strong></td><td>Zhen Chen, Qing Xu, Jinlin Wu, Biao Yang, Yuhao Zhai, Geng Guo, Jing Zhang, Yinlu Ding, Nassir Navab, Jiebo Luo</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI, cs.MM</td></tr><tr><td><strong>一句话</strong></td><td>用 50 段真实手术片段 + 四层「手术合理性金字塔」+ 四位持证外科医生盲评，量化出 Veo-3 在手术视频预测上「画面像、逻辑全错」的鸿沟。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视频生成模型被越来越多地当作「世界模型」来用，理由是它们在自然场景里表现出了对重力、碰撞、遮挡的粗粒度理解。但自然场景的物理规则是所有人共享的常识；手术不是。手术里的因果链条由解剖学、生物力学和术式流程共同决定：钳子往左拨还是往右拨、切断血管后该不该出血、电凝之后组织变成什么颜色，这些都不是「常识物理」能推出来的，而是外科医生训练多年才内化的专家知识。</p><p>论文问的问题非常具体：把当前最强的视频生成模型之一 Veo-3 放到手术场景里做零样本未来预测，它离一个「手术世界模型」还有多远？重要性在于，手术模拟器、术前预演、术中风险预警这些临床应用一旦落地，价值极高但容错率极低。如果我们只用 FVD、CLIP 分数这类通用指标去衡量，一个画面漂亮但操作荒谬的模型会被误判为「接近可用」。这篇论文的贡献就是把这个误判暴露出来，并给出可复用的度量工具。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>已有的视频生成评测体系（VBench 这类）关注的是画面清晰度、时序抖动、文本一致性等表观维度，对「这个动作在专业上是否讲得通」完全没有表达能力。物理向的 benchmark 关注的是刚体自由落体、流体连续性这类通用规律，同样落不到解剖结构上。</p><p>手术域内并非没有生成工作：Endora 把视频生成模型当作内窥镜模拟器，SurgSora 做物体感知的可控手术视频生成。但这些工作的目标是「合成好看且可控的手术视频」，评价手段仍然是通用画质指标或有限的人工打分，没有把「器械操作是否技术正确」「组织反馈是否符合生物力学」「术式意图是否合理」拆开来独立度量。换句话说，缺口不在于没人做手术视频生成，而在于没有一把能区分「模仿外观」和「理解因果」的尺子。之所以此前没人造这把尺子，很直接的原因是它需要多位持证外科医生逐段视频打分，成本高且无法自动化。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>出发点是一个可观察到的失衡：2024 至 2025 年间，Veo-3 这类模型在自然视频上展现出被称为 Chain-of-Frames 的逐帧推理能力，社区据此推断视频模型是「零样本学习者和推理者」。同时，医学基础模型的讨论也在升温。把两者叠加，很自然会产生一个假设：既然模型在自然视频上学到了物理，在医学视频上是不是也学到了生理？</p><p>但一个认真的研究者会立刻意识到，这个假设无法用现有指标验证——通用指标测不出手术逻辑。于是问题变成了「怎么测」。此时手术领域自身的知识结构提供了线索：外科教学本来就是分层的，先看得清（视野），再动得对（器械操作），再判断组织反应（反馈），最后才是术式策略（意图）。把这个教学层级直接搬成评测层级，就得到了 SPP 金字塔。有了分层，就能回答「模型停在哪一层」，而不是笼统地说「好」或「不好」。剩下的工程决策——单帧输入、8 秒时长、1/3/8 秒三个检查点、基线与阶段感知两套 prompt——都是为了把「不会」和「没被告知」这两种失败区分开。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>视频生成模型学到的是像素在时空上如何延续，不是动作在因果上如何延续。在自然场景里这两者高度重合，因为常识物理本身就写在像素的统计规律里；在手术场景里它们分道扬镳，因为「下一步该做什么」由术式规范决定，而术式规范在互联网视频的像素统计中几乎不留痕迹。所以模型能把镜面反光、组织质感、血液颜色渲染得让外科医生惊讶，却会凭空生成一把不存在的器械去做一个不存在的操作。把评测从「像不像」改成分层的「对不对」，这个落差就会以数字的形式显形。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>数据。</strong> SurgVeo 取两条赛道：腹腔镜赛道来自 AutoLaparo 的 3 台腹腔镜子宫切除术（1920×1080，25 fps），划分为 7 个阶段；神经外科赛道来自 PitVis 的 3 台内镜垂体手术（1280×720，24 fps），划分为 12 个阶段。共切出 50 段样本，腹腔镜 18 段、神经外科 32 段。每段样本包含一张输入帧（某个术中动作发生之前的最后一帧）和紧随其后的 8 秒真实视频作为参考。</p><p><strong>生成。</strong> Veo-3（Google Flow 平台上的 Veo-3.0-quality）不做任何微调，输入这张帧加一段文本，输出 8 秒续写。文本有两种：基线 prompt 只说术式类型和画质、解剖真实性要求；阶段感知 prompt 额外插入一句「当前阶段是 [STAGE]」。</p><p><strong>评测。</strong> 两位腹腔镜医生独立评腹腔镜赛道，两位神经外科医生独立评神经外科赛道。医生先看 8 秒真实参考建立上下文，再对生成视频在 1 秒、3 秒、8 秒三个时间点、按 SPP 四个维度各打 1 到 5 分。以一个具体例子看整条链路：输入帧停在硬脑膜上准备涂生物胶的瞬间，真实续写是注射生物胶；Veo-3 生成的是用棉片擦拭硬脑膜。画面质量可接受，于是视觉感知得分不低，但器械、操作、反馈、意图四项全错——这正是论文反复展示的失败形态。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：模型停在金字塔的哪一层？</strong> 用 SPP 四维分数做对比。视觉感知维度稳定偏高，腹腔镜基线 prompt 首秒 3.72 ± 0.24，神经外科 3.88 ± 0.09；而高层维度在 8 秒处塌到 2 分以下：腹腔镜阶段感知 prompt 下器械操作 1.69 ± 0.20、环境反馈 1.53 ± 0.12、手术意图 1.81 ± 0.20；神经外科的手术意图更低，基线与阶段感知分别是 1.13 ± 0.04 和 1.17 ± 0.02。结论是模型牢牢卡在金字塔底层。</p><p><strong>问题二：失败是逐渐累积还是一开始就有？</strong> 用 1/3/8 秒三点对比。视觉感知几乎不衰减，高层维度单调下滑：腹腔镜基线 prompt 的环境反馈从首秒 3.06 ± 0.08 掉到 8 秒 1.64 ± 0.12，作者记为近 46% 的跌幅；手术意图从 3.11 ± 0.16 掉到 1.61 ± 0.16。说明外观可以长期维持，逻辑会随预测时长复合式崩坏。</p><p><strong>问题三：把手术阶段明确告诉模型能否救回来？</strong> 对比两套 prompt。结论是没有一致提升，个别项反而更低（腹腔镜首秒器械操作，阶段感知 3.22 ± 0.16 低于基线 3.36 ± 0.20）。作者据此判断瓶颈不是信息缺失而是无法把「血管结扎」这样的抽象概念翻译成一串物理上成立的动作。</p><p><strong>问题四：错误具体长什么样？</strong> 统计基线 prompt 下的错误类型分布。基础画质畸变只占腹腔镜 6.2%、神经外科 2.8%；超过 93% 是逻辑类失败。四类主导错误为手术意图错误（21.9% / 22.0%）、环境反馈错误（17.2% / 22.0%）、器械错误（17.2% / 17.7%）、不恰当操作（15.6% / 21.3%），在神经外科这四类合计占 83%。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版：</strong> 论文构建了 SurgVeo，50 段来自腹腔镜子宫切除术与内镜垂体手术的样本，任务是从单帧零样本续写 8 秒。评价用四层的手术合理性金字塔，由视觉感知、器械操作、环境反馈、手术意图组成，四位持证外科医生在 1/3/8 秒三点打 5 分制。Veo-3 在视觉感知稳定 3.2 到 3.9 分，在其余三层于 8 秒处普遍跌到 2 分以下，神经外科意图低至 1.13。显式告知手术阶段没有带来一致改善，说明缺的是知识而不是上下文。超过 93% 的错误属于手术逻辑，而非画质。</p><p><strong>3 句话版：</strong> Veo-3 能把手术画面渲染得让外科医生称为「清晰得惊人」，却不理解器械该怎么动、组织该如何反应、这一步为什么要做。分层评测把这个落差量化成了从 3.9 分到 1.1 分的断崖。补充术式阶段文本无效，指向表征结构而非信息量的问题。</p><p><strong>1 句话版：</strong> 通用视频模型在手术域达到了视觉可信，但没有达到手术可信，两者之间的差距是本文第一次给出的定量证据。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：把生成视频与那一段真实续写对照打分，可以度量「手术合理性」。手术的未来是多解的——同一帧之后，一位医生可能先止血再分离，另一位可能先分离再止血，两者都专业正确。SPP 的意图维度评分标准要求「与当前术式一致、与参考视频对照」，这会把「专业上成立但与实际发生不同」的续写压到低分区。如果 8 秒处 1.1 到 1.8 分的低分里有相当比例来自这种预测多解性而非真正的逻辑违规，那么「模型缺乏因果理解」这一核心结论就要打折扣。</p><p>论文提供了三条间接证据来对冲这一风险：错误类型统计里明确列出了幻觉器械、把凝胶海绵当刚体整块吸起来这类硬性违规，这些不受多解性影响；高分案例分析显示模型在「无操作停顿」这类几乎无歧义的片段上能拿高分，说明打分不是一律压低；两位同专业医生的标准差普遍很小（多数在 0.2 以内）。缺的证据是把真实参考本身或另一台手术的真实片段混入盲评作为对照上限——没有这个 ceiling，读者无法判断 1.6 分的意图得分里有多少是模型的问题，多少是协议的问题。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做的最小验证，目标就是估计上面那个 ceiling。取 SurgVeo 公开发布的 10 段样本，每段准备三种 8 秒续写：真实参考本身、同一台手术同一阶段但不同时间点的真实片段、Veo-3 生成结果。三者随机打乱后交给两位外科医生按 SPP 四维盲评。只需测一件事：第二类（真实但非对应）片段在意图与器械操作维度的得分。如果它稳定在 4 分以上，说明医生打分主要针对专业正确性而非与参考的逐帧吻合，论文结论成立；如果它掉到 2 到 3 分区间，说明协议本身惩罚了合理的多解性，那么模型与人的差距被系统性夸大了，需要把评分标准改成「是否存在某个专业上成立的解释」。这个实验不需要复现任何生成模型。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是替代解释：Veo-3 的失败可能主要来自条件信息不足，而不是缺乏手术知识。单张帧加一句文本，在信息论上根本不足以确定下一步——真实医生做判断时依赖的是前面几分钟的操作史、患者影像、器械托盘上有什么。论文的阶段感知 prompt 只补了一个粗粒度标签，不能证伪这个解释。</p><p>具体设计：把输入从单帧改成前 8 秒真实视频片段（Veo-3 支持视频延续），保持其余协议不变，重跑腹腔镜赛道 18 段。如果器械操作与意图分数显著回升，说明瓶颈在条件带宽而非知识；如果仍然停在 2 分以下，论文的结论就大幅加固。进一步的加强版是把「当前托盘上可用的器械列表」写进 prompt——器械幻觉占错误的 17% 左右，如果这一项能被文本约束消掉，说明模型并非不知道器械长什么样，而是缺少约束通道。可以预见方法失败的场景还有一类：真实手术里存在大量「什么也没发生」的片段，模型在这类片段上得分高（论文附录的神经外科高分案例正是一次操作暂停），如果 benchmark 中此类片段占比上升，整体分数会虚高。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>驱动这个想法的局限是：SPP 依赖四位医生，成本高、不可扩展，且如上所述会把多解性误判为错误。一个非增量的重构是把评测目标从「生成的视频对不对」换成「模型的信念分布对不对」——不评价单条续写，而评价模型对下一步动作的概率分布是否与专家群体的分布一致。</p><p>可以借用的相邻领域工具是临床决策研究里的成熟做法：同一术中场景请 N 位医生独立写出「下一步会做什么」，得到一个动作分布而非单一答案；这与 NLP 里用多参考评价机器翻译、以及 RLHF 里用多标注者分歧建模不确定性是同一类思路。做法上，先让 VLM 把生成视频压成一个结构化的动作三元组（器械、目标解剖结构、操作类型），再与专家动作分布计算交叉熵或覆盖率。这样评测就自动化了，也天然容纳多解。</p><p>第一个实验很轻：只在 SurgVeo 的神经外科赛道上做，请 4 位医生对 32 个输入帧各自写出 3 个可接受的下一步动作三元组，构成参考分布；对 Veo-3 采样 10 条续写，人工（或 VLM 辅助）抽取三元组，计算落在参考集合内的比例。把这个比例与论文里的意图得分做相关性分析——若两者高度相关，说明新指标可以低成本替代专家评分；若不相关，则两个指标各自捕捉了不同的失效模式，这本身也值得报告。</p>',41)])])}const c=e(n,[["render",s]]);export{g as __pageData,c as default};
